  `total` decimal(12,2) NOT NULL,
  `payment_method` enum('Cash','Online Payment','Card') NOT NULL,
  `amount_tendered` decimal(12,2) DEFAULT NULL,
  `change_due` decimal(12,2) DEFAULT NULL,
  `payment_reference` varchar(60) DEFAULT NULL,
  `status` enum('Completed','Refunded') NOT NULL DEFAULT 'Completed',
  `refunded_at` datetime DEFAULT NULL,
  `refunded_by` int(11) DEFAULT NULL,
  `refund_reason` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `txn_no` (`txn_no`),
  KEY `user_id` (`user_id`),
  KEY `refunded_by` (`refunded_by`),
