  CONSTRAINT `sales_ibfk_2` FOREIGN KEY (`refunded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5622 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
